            for(ci=0;ci<chars;ci=ci+1)begin
                bitmap=reference_glyph(text >> ((chars-1-ci)*8));
                for(gy=0;gy<7;gy=gy+1)for(gx=0;gx<8;gx=gx+1)begin
                    lit=0;if(gx<5)lit=bitmap[(6-gy)*5+4-gx];
                    for(sy=0;sy<scale;sy=sy+1)for(sx=0;sx<scale;sx=sx+1)
                        expect_pixel(px+(ci*8+gx)*scale+sx,py+gy*scale+sy,lit?foreground:background);
                end
            end
        end
    endtask
    task expect_zh;
        input integer px,py,width;
        input [287:0] label;
        input [23:0] foreground,background;
        integer gx,gy;
        reg [23:0] underlay;
        begin
            // Covers row 7->8, both halves, all 16 rows, padding and full clipping rectangle.
            for(gy=0;gy<16;gy=gy+1)for(gx=0;gx<width;gx=gx+1)begin
                underlay=background;
                if(background==BG && px+gx>=31 && px+gx<=544 && py+gy>=143 && py+gy<=280)
                    underlay=reference_scope(px+gx,py+gy,wave_previous,wave_current,scope_gain,wave_valid);
                expect_pixel(px+gx,py+gy,reference_lit(label,gx,gy)?foreground:underlay);
            end
        end
    endtask
    task expect_digits;
        input integer px,py,chars,value;
        input [23:0] foreground;
        reg [287:0] label;
        begin
            label=reference_number(ZH_BLANK,0,chars,value);
            expect_zh(px,py,chars*8,label,foreground,BG);
        end
    endtask
    task expect_wait;
        integer gx,gy;
        reg [23:0] expected;
        begin
            for(gy=0;gy<16;gy=gy+1)for(gx=0;gx<80;gx=gx+1)begin
                expected=reference_scope(256+gx,204+gy,0,0,0,0);
                if(reference_lit(ZH_WAIT,gx,gy))expected=AMBER;
                expect_pixel(256+gx,204+gy,expected);
            end
        end
    endtask
    task expect_wave;
        input integer previous,current,gain;
        integer p,px,py;
        begin
            wave_previous=previous;wave_current=current;scope_gain=gain;wave_valid=1;
            for(p=0;p<6;p=p+1)begin
                case(p)0:px=32;1:px=33;2:px=34;3:px=35;4:px=542;5:px=543;endcase
                for(py=144;py<=279;py=py+1)
                    expect_pixel(px,py,reference_scope(px,py,previous,current,gain,1));
            end
        end
    endtask

    // Actual RTL P3 pixels. SCENE=0 guide,1 free,2 done,3 wait,4 wrong,5 extremes.
    integer output_file,px,py,address,scene;
    reg [2047:0] output_path;
    function signed [15:0] simulated_sample;
        input integer index;
        begin simulated_sample=$rtoi(12000.0*$sin(6.283185307179586*261.626*index*4.0/93750.0));end
    endfunction
    initial begin
        reset_renderer;defaults;
        scene=0;if($value$plusargs("SCENE=%d",scene))begin end
        keys=1;level_dbfs=-12;peak_percent=37;pressure1=164;flags=8'h24;
        guide_active=1;cue_mask=1;next_mask=1;beat_progress=150;scope_gain=1;
        case(scene)
            1:begin guide_active=0;keys=12'h481;timbre=15;end
            2:begin guide_done=1;guide_step=42;beat_progress=255;keys=0;end
            3:begin wave_valid=0;note_valid=0;keys=0;flags=8'h18;end
            4:begin keys=3;wrong_mask=2;flags=8'hc0;end
            5:begin scope_gain=15;level_dbfs=-128;pitch=-256;flags=8'hff;end
        endcase
        expect_zh(32,16,256,ZH_TITLE,CYAN,BG);
        if(guide_done)expect_zh(368,16,256,ZH_DONE_TITLE,GREEN,BG);
        else if(guide_active)expect_zh(368,16,256,ZH_GUIDE,AMBER,BG);
        else expect_zh(368,16,256,ZH_FREE,CYAN,BG);
        expect_zh(32,40,256,reference_timbre_label(timbre),TEXT,BG);
        if(!wave_valid)expect_wait;
        output_file=32'h80000001;
        if($value$plusargs("PPM=%s",output_path))begin
            output_file=$fopen(output_path,"w");if(output_file==0)$fatal(1,"Cannot open normal PPM");
        end
        $fwrite(output_file,"P3\n# Chinese normal UI, renderer RTL, synthetic PCM\n640 480\n255\n");
        for(py=0;py<480;py=py+1)for(px=0;px<640;px=px+1)begin
            address=0;if(px>=32 && px<=543)address=(px-32)>>1;
            wave_current=simulated_sample(address);wave_previous=simulated_sample(address==0?0:address-1);
            if(scene==5)begin wave_current=32767;wave_previous=-32768;end
            sample_pixel(px,py);
            case({red,green,blue})BG,PANEL,BORDER,GRID,TEXT,MUTED,CYAN,GREEN,AMBER,ALERT:begin end
                default:$fatal(1,"Unexpected normal palette %06h",{red,green,blue});endcase
            $fwrite(output_file,"%0d %0d %0d\n",red,green,blue);
        end
        if(output_file!=32'h80000001)$fclose(output_file);
        $display("HDMI_LIVE_PREVIEW_PASS RTL simulation scene=%0d checks=%0d",scene,checks);$finish;
    end
    initial begin #10000000;$fatal(1,"Normal preview timeout");end
endmodule
